engine.profileEmailHash:
function profileEmailHash(email) {
  var e = String(email == null ? "" : email).toLowerCase().trim();
  if (!e) return Promise.resolve(null);
  if (!window.crypto || !window.crypto.subtle) return Promise.resolve(null);
  return window.crypto.subtle.digest("SHA-256", new TextEncoder().encode(e))
    .then(function (buf) {
      var out = "";
      new Uint8Array(buf).forEach(function (b) { out += ("0" + b.toString(16)).slice(-2); });
      return out.slice(0, 32);
    })
    .catch(function () { return null; });
}

// → { key, userId, initials, trophyCount, lastSeenAt } | null
// Every install that has ever pushed under this email hash, newest first.
// The index used to hold ONE key per hash — the last install to push — so a
// second machine signing in with the same address overwrote the pointer to
// the machine that actually held the trophies. keys[] is the fix; the bare
// key field is still read for entries written before it existed.

engine.profileLookup:
function profileLookup(hash) {
  if (!hash) return Promise.resolve(null);
  var url = "https://raw.githubusercontent.com/apndrewn/eli-data/main/usage/_profiles.json";
  return fetch(url + "?t=" + Date.now(), { cache: "no-store" })
    .then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) throw new Error("index HTTP " + r.status);
      return r.json();
    })
    .then(function (j) {
      if (!j || !j.profiles) return null;
      var e = j.profiles[hash];
      if (!e) return null;
      var keys = [];
      if (Array.isArray(e.keys)) {
        e.keys.forEach(function (k) {
          k = String(k || "").trim();
          if (k && keys.indexOf(k) === -1) keys.push(k);
        });
      }
      if (e.key && keys.indexOf(e.key) === -1) keys.push(e.key);
      if (!keys.length) return null;
      e.keys = keys;
      e.key = keys[0];
      return e;
    });
}

// Pull the telemetry digest and reduce it to what a restore needs.
// → { trophyIds, trophyDates, stats, initials, lastSeenAt } | null

engine.profileFetchDigest:
function profileFetchDigest(key) {
  if (!key) return Promise.resolve(null);
  var base = "https://raw.githubusercontent.com/apndrewn/eli-data/main/usage/";
  return fetch(base + encodeURIComponent(key) + ".json?t=" + Date.now(),
    { cache: "no-store" })
    .then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) throw new Error("digest HTTP " + r.status);
      return r.json();
    })
    .then(function (j) {
      var f = j && j.fleet;
      if (!f) return null;
      var ids = Array.isArray(f.trophyIds) ? f.trophyIds.map(String).filter(Boolean) : [];
      var dates = (f.trophyDates && typeof f.trophyDates === "object") ? f.trophyDates : {};
      var stats = (f.stats && typeof f.stats === "object") ? f.stats : null;
      if (!ids.length && !stats) return null;
      return {
        trophyIds: ids,
        trophyDates: dates,
        stats: stats,
        initials: f.initials || null,
        lastSeenAt: f.lastSeenAt || null,
      };
    });
}

// Worth offering? Only when the backup actually holds more than this
// install does. Restoring onto an account that's already ahead would lose
// progress, which is the opposite of the point.

engine.profileWorthRestoring:
function profileWorthRestoring(remote, localTrophyCount) {
  if (!remote) return false;
  var n = Array.isArray(remote.trophyIds) ? remote.trophyIds.length : 0;
  return n > (localTrophyCount || 0);
}

// Backups belonging to these initials, newest first. The hash index only
// answers "which profile is exactly mine" — it can't help when the email
// changed between installs, which is the common case after a forced reset.
// Listing by initials covers that, and scoping to the current user's own
// initials keeps colleagues' profiles out of the picker.
// → [{ key, initials, trophyIds, trophyDates, stats, lastSeenAt }]

engine.profileListCandidates:
function profileListCandidates(initials, excludeKey, diag, fetchDigest) {
  diag = diag || {};
  var want = String(initials || "").toLowerCase().trim();
  diag.initials = want;
  if (!want) { diag.listError = "no initials"; return Promise.resolve([]); }
  if (typeof fetchDigest !== "function") {
    diag.listError = "no digest fetcher passed";
    return Promise.resolve([]);
  }
  var api = "https://api.github.com/repos/apndrewn/eli-data/contents/usage";
  return fetch(api + "?t=" + Date.now(), { cache: "no-store" })
    .then(function (r) {
      diag.listStatus = r.status;
      if (!r.ok) throw new Error("list HTTP " + r.status);
      return r.json();
    })
    .then(function (files) {
      if (!Array.isArray(files)) return [];
      var keys = files
        .map(function (f) { return String(f && f.name || ""); })
        .filter(function (n) { return /\.json$/.test(n) && n.charAt(0) !== "_"; })
        .map(function (n) { return n.replace(/\.json$/, ""); })
        .filter(function (k) {
          if (excludeKey && k === excludeKey) { diag.excluded = k; return false; }
          // "an-xokse6dw" and the legacy bare "an" both belong to AN.
          return k === want || k.indexOf(want + "-") === 0;
        });
      diag.matchedKeys = keys.slice();
      return Promise.all(keys.map(function (k) {
        return fetchDigest(k)
          .then(function (d) { if (!d) return null; d.key = k; return d; })
          .catch(function () { return null; });
      }));
    })
    .then(function (rows) {
      var ok = rows.filter(Boolean);
      diag.digestsOk = ok.length;
      return ok.sort(function (a, b) {
        return String(b.lastSeenAt || "").localeCompare(String(a.lastSeenAt || ""));
      });
    })
    .catch(function (err) { diag.listError = (err && err.message) || "unknown"; return []; });
}

view.renderProfileRestore:
function renderProfileRestore(opts) {
  opts = opts || {};
  var list = (opts.profiles || []).slice();
  var onRestore = typeof opts.onRestore === "function" ? opts.onRestore : function () {};
  var onDecline = typeof opts.onDecline === "function" ? opts.onDecline : function () {};
  if (!list.length) return null;

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  function when(iso) {
    if (!iso) return "date unknown";
    try {
      var d = new Date(iso);
      var day = d.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
      var t = d.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
      return day + " at " + t;
    } catch (e) { return "date unknown"; }
  }
  function statLine(st) {
    if (!st) return "no stats saved";
    var bits = [];
    if (st.totalActiveDays) bits.push(st.totalActiveDays + " active days");
    if (st.docsReviewed) bits.push(st.docsReviewed + " docs");
    if (st.errorsFixed) bits.push(st.errorsFixed + " fixes");
    if (st.draftsCreated) bits.push(st.draftsCreated + " drafts");
    if (st.risksFound) bits.push(st.risksFound + " risks");
    return bits.length ? bits.join(" · ") : "no stats saved";
  }

  var sel = 0;

  var ov = document.createElement("div");
  ov.className = "_eli3_pr_overlay";
  ov.style.cssText =
    "position:fixed;inset:0;z-index:9650;background:rgba(8,17,28,0.58);" +
    "display:flex;align-items:center;justify-content:center;padding:14px;" +
    "box-sizing:border-box;font-family:Inter,system-ui,sans-serif;";

  ov.innerHTML =
    '<div style="display:flex;flex-direction:column;box-sizing:border-box;' +
      'width:100%;max-width:430px;max-height:88vh;background:#fff;' +
      'border:1px solid #0d1b2a;box-shadow:0 18px 48px rgba(0,0,0,0.42);">' +
      '<div style="flex:0 0 auto;background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);' +
        'border-bottom:3px solid #c9a227;padding:18px;">' +
        '<div style="font-size:8px;font-weight:700;color:#c9a227;text-transform:uppercase;' +
          'letter-spacing:2.5px;margin-bottom:6px;">' +
          (list.length === 1 ? 'Previous profile found' : list.length + ' previous profiles found') +
        '</div>' +
        '<div style="font-family:Georgia,serif;font-size:22px;color:#fff;line-height:1.2;">' +
          'Welcome back.</div>' +
        '<div style="font-size:12px;color:#8fa6c7;margin-top:6px;line-height:1.5;">' +
          'ELI has ' + (list.length === 1 ? 'a backup' : 'backups') +
          ' of your trophies and stats. Pick which to restore.</div>' +
      '</div>' +
      '<div data-pr-list style="flex:1 1 auto;min-height:0;overflow-y:auto;padding:14px 14px 4px;"></div>' +
      '<div style="flex:0 0 auto;padding:12px 14px;border-top:1px solid #e4e8eb;' +
        'background:#fafbfc;display:flex;gap:8px;">' +
        '<button data-pr-no style="flex:0 0 auto;padding:0 14px;height:38px;border-radius:0;' +
          'cursor:pointer;font-size:10px;font-weight:800;letter-spacing:1px;' +
          'text-transform:uppercase;color:#546e7a;' +
          'background:linear-gradient(to bottom,#f7f9fa 0%,#dce3e8 100%);' +
          'border:1px solid #b0bec5;border-top:1px solid #cfd8dc;' +
          'box-shadow:inset 0 1px 0 #fff;">Not now</button>' +
        '<button data-pr-yes style="flex:1;height:38px;border-radius:0;cursor:pointer;' +
          'font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;' +
          'color:#fff;background:linear-gradient(to bottom,#1e88e5 0%,#0d47a1 100%);' +
          'border:1px solid #0a3880;box-shadow:inset 0 1px 0 rgba(255,255,255,0.28);">' +
          'Restore this profile</button>' +
      '</div>' +
    '</div>';

  var listEl = ov.querySelector("[data-pr-list]");
  var rows = [];
  list.forEach(function (p, i) {
    var n = (p.trophyIds || []).length;
    var row = document.createElement("div");
    row.style.cssText =
      "padding:12px 13px;margin-bottom:9px;cursor:pointer;box-sizing:border-box;" +
      "border:1px solid #d7dde3;background:#fff;transition:border-color .15s ease,background .15s ease;";
    row.innerHTML =
      '<div style="display:flex;align-items:baseline;gap:8px;">' +
        '<div style="font-size:13px;font-weight:800;color:#0d47a1;">' +
          esc(p.initials || p.key) + '</div>' +
        '<div style="font-size:11px;color:#78909c;">backed up ' + esc(when(p.lastSeenAt)) + '</div>' +
      '</div>' +
      '<div style="display:flex;align-items:baseline;gap:7px;margin-top:8px;">' +
        '<span style="font-size:22px;font-weight:800;color:#1a2327;line-height:1;">' + n + '</span>' +
        '<span style="font-size:10px;font-weight:700;color:#90a4ae;text-transform:uppercase;' +
          'letter-spacing:1px;">' + (n === 1 ? 'trophy' : 'trophies') + '</span>' +
      '</div>' +
      '<div style="font-size:11.5px;color:#546e7a;margin-top:6px;line-height:1.5;">' +
        esc(statLine(p.stats)) + '</div>' +
      '<div style="font-size:10px;color:#b0bec5;margin-top:5px;font-family:Consolas,monospace;">' +
        esc(p.key) + '</div>';
    row.onclick = function () { sel = i; paint(); };
    rows.push(row);
    listEl.appendChild(row);
  });

  function paint() {
    rows.forEach(function (r, i) {
      var on = i === sel;
      r.style.borderColor = on ? "#1565c0" : "#d7dde3";
      r.style.background = on ? "#f5faff" : "#fff";
      r.style.boxShadow = on ? "inset 3px 0 0 #1565c0" : "none";
    });
  }
  paint();

  function close() { if (ov.parentNode) ov.parentNode.removeChild(ov); }

  var yes = ov.querySelector("[data-pr-yes]");
  ov.querySelector("[data-pr-no]").onclick = function () { close(); onDecline(); };
  yes.onclick = function () {
    yes.disabled = true;
    yes.textContent = "Restoring…";
    Promise.resolve(onRestore(list[sel]))
      .then(function () { close(); })
      .catch(function (err) {
        yes.disabled = false;
        yes.textContent = "Restore this profile";
        if (typeof showToast === "function") {
          showToast("Restore failed: " + ((err && err.message) || "unknown"), "err");
        }
      });
  };

  document.body.appendChild(ov);
  return { close: close, el: ov };
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["profile_restore"];
  if (!bundle) return;
  var E = bundle._eliEngineFns || {};
  var renderProfileRestore = bundle._eliViewFns && bundle._eliViewFns.renderProfileRestore;
  if (!E.profileEmailHash || !E.profileLookup || !E.profileFetchDigest ||
      !E.profileWorthRestoring || !renderProfileRestore) {
    eli.log.event("tool", "profile_restore_init_missing_fns", {});
    return;
  }

  var _open = false;

  function _localTrophyCount() {
    return eli.storage.get("stats", "eli_user_stats")
      .then(function (row) {
        if (!row) {
          try { var raw = eli.compat.lsGet("eli_user_stats"); if (raw) row = JSON.parse(raw); }
          catch (e) { /* malformed blob — treat as empty */ }
        }
        var ids = row && Array.isArray(row.unlockedTrophies) ? row.unlockedTrophies : [];
        return ids.length;
      })
      .catch(function () { return 0; });
  }

  // Same write path as eli-admin's restore_trophies: IDB stats row first,
  // then the localStorage blob, so both views of the data agree.
  function _apply(remote) {
    var ids = remote.trophyIds.map(String);
    var now = Date.now();
    function patch(stats) {
      stats = (stats && typeof stats === "object") ? stats : {};
      var prev = Array.isArray(stats.unlockedTrophies) ? stats.unlockedTrophies.map(String) : [];
      // Merge, never replace — anything earned on THIS install since the
      // reset is real progress and must survive the restore.
      var next = prev.concat(ids.filter(function (id) { return prev.indexOf(id) === -1; }));
      stats.unlockedTrophies = next;
      var dates = (stats.unlockedDates && typeof stats.unlockedDates === "object") ? stats.unlockedDates : {};
      next.forEach(function (id) {
        if (!dates[id]) dates[id] = remote.trophyDates[id] || now;
      });
      stats.unlockedDates = dates;
      if (remote.stats) {
        // Counters take the HIGHER of the two — the backup may be a few
        // sessions stale, and a restore should never move a number down.
        Object.keys(remote.stats).forEach(function (k) {
          var rv = Number(remote.stats[k]);
          if (!isFinite(rv)) return;
          var lv = Number(stats[k]);
          stats[k] = isFinite(lv) ? Math.max(lv, rv) : rv;
        });
      }
      return stats;
    }
    return eli.storage.get("stats", "eli_user_stats").then(function (row) {
      if (!row) {
        try { var raw0 = eli.compat.lsGet("eli_user_stats"); if (raw0) row = JSON.parse(raw0); }
        catch (e0) { /* malformed blob — start clean */ }
      }
      var patched = patch(row);
      patched.stat_id = "eli_user_stats";
      return eli.storage.put("stats", patched);
    }).then(function () {
      try {
        var raw = eli.compat.lsGet("eli_user_stats");
        var blob = raw ? JSON.parse(raw) : {};
        eli.compat.lsSet("eli_user_stats", JSON.stringify(patch(blob)));
      } catch (e) { /* IDB row is the source of truth; blob is a mirror */ }
      if (eli.activity && typeof eli.activity.add === "function") {
        eli.activity.add({
          type: "profile.restore",
          icon: "🏆",
          label: "Previous profile restored",
          summary: ids.length + " trophies and your stats are back",
          timestamp: now,
        });
      }
      eli.log.event("tool", "profile_restored", { trophies: ids.length });
      // The write lands in IDB + the localStorage blob, but the sidebar
      // stats, trophy chip and gallery were all rendered from the values
      // read at boot. Without a reload the user sees the OLD numbers and
      // concludes the restore failed — so say it plainly rather than
      // flashing a toast that scrolls away.
      var msg = "Restored " + ids.length + " trophies" +
        (remote.stats ? " and your stats" : "") +
        ". Close and reopen ELI to see them — the sidebar and Trophy " +
        "Gallery still show what was loaded when you opened it.";
      if (eli.ui && typeof eli.ui.alert === "function") {
        return eli.ui.alert({ title: "🏆 Profile restored", message: msg });
      }
      if (typeof showToast === "function") showToast(msg, "ok");
    });
  }

  // Every backup this user could plausibly own, newest first. The hash
  // index gives an exact match when the email is unchanged; the initials
  // scan covers a reset that also changed the email, which is the case
  // that left people stranded.
  function _candidates(diag) {
    diag = diag || {};
    var ident = null;
    try { ident = eli.tools.userIdentity(); } catch (e) { ident = null; }
    var initials = "";
    try {
      var nm = String((ident && (ident.name || ident.firstName)) || "").trim();
      initials = nm.split(/\s+/).map(function (w) { return w.charAt(0); }).join("").slice(0, 2);
      if (!initials && ident && ident.email) initials = String(ident.email).slice(0, 2);
    } catch (e) { /* fall through to the hash path only */ }
    var mineKey = null;
    try { mineKey = String(eli.settings.get("user_id") || "").toLowerCase() || null; } catch (e) {}

    // Every install that pushed under this exact email — plural, because a
    // person with two machines has two. Tagged .exact: an identical address
    // is proof of ownership, which is what lets the caller offer these
    // without any of the once-only gating a fuzzy match needs.
    var exact = E.profileEmailHash(ident && ident.email)
      .then(function (hash) { diag.hash = hash || null; return E.profileLookup(hash); })
      .then(function (entry) {
        diag.indexHit = !!entry;
        if (!entry) return [];
        var keys = (entry.keys || [entry.key]).filter(function (k) {
          return k && k !== mineKey;             // my own file isn't a backup
        });
        diag.exactKeys = keys.slice();
        return Promise.all(keys.map(function (k) {
          return E.profileFetchDigest(k).then(function (d) {
            if (!d) return null;
            d.key = k;
            d.exact = true;
            d.initials = d.initials || entry.initials;
            d.lastSeenAt = d.lastSeenAt || entry.lastSeenAt;
            return d;
          }).catch(function () { return null; });
        })).then(function (rows) { return rows.filter(Boolean); });
      })
      .catch(function (err) { diag.indexError = (err && err.message) || "unknown"; return []; });

    // profileFetchDigest is passed in: build_tool.js splits engine.js at
    // every column-0 function, so siblings are separate bundle entries and
    // cannot call each other. init is the only place that can see both.
    return Promise.all([exact, E.profileListCandidates(initials, mineKey, diag, E.profileFetchDigest)])
      .then(function (res) {
        var out = [];
        var seen = {};
        (res[0] || []).forEach(function (d) {
          if (d && d.key && !seen[d.key]) { seen[d.key] = true; out.push(d); }
        });
        (res[1] || []).forEach(function (d) {
          if (d && d.key && !seen[d.key]) { seen[d.key] = true; out.push(d); }
        });
        // A backup with nothing in it is noise in the picker.
        return out.filter(function (d) {
          return (d.trophyIds && d.trophyIds.length) || d.stats;
        });
      })
      .catch(function (err) {
        eli.log.event("tool", "profile_restore_lookup_failed", { msg: err && err.message });
        return [];
      });
  }
  function _offer(profiles) {
    if (_open || !profiles.length) return;
    _open = true;
    renderProfileRestore({
      profiles: profiles,
      onRestore: function (chosen) {
        return _apply(chosen).then(function () { _open = false; });
      },
      onDecline: function () { _open = false; },
    });
  }

  // User-initiated: always looks, always offers, ignores a past decline and
  // the worth-restoring test — if they came here deliberately, show them
  // what exists and let them judge.
  function _manual() {
    var diag = {};
    _candidates(diag).then(function (profiles) {
      if (!profiles.length) {
        // Say WHY. An empty result from a rate-limited listing, a hash miss
        // and a genuine absence of backups are three different problems and
        // shrugging at all three is what made this undebuggable.
        var why = diag.listError ? ("lookup failed: " + diag.listError)
          : !diag.matchedKeys || !diag.matchedKeys.length
            ? ("no backups match initials \"" + (diag.initials || "?") + "\"")
            : "backups found but empty: " + diag.matchedKeys.join(", ");
        showToast("No profiles to restore — " + why, "warn");
        eli.log.event("tool", "profile_restore_empty", diag);
        return;
      }
      _offer(profiles);
    });
  }

  eli.register({
    tile: { app_profile_restore: _manual },
    profile_restore: { open: _manual },
  });

  // Automatic offer — only for an install that has NO trophies of its own.
  // A zero count is the signature of a wipe; anyone with progress here
  // doesn't need rescuing and shouldn't be interrupted.
  //
  // The marker records WHEN we offered, not merely that we did. A boolean
  // meant one wipe was rescuable and every later one was silent: you'd be
  // wiped, decline or dismiss, use ELI for months, get wiped again, and
  // never be asked. Re-offering when a backup has been written since the
  // last offer is the honest signal — it means real progress was made and
  // then lost again. Written when the dialog is SHOWN, so dismissing it
  // any way at all still counts.
  var OFFERED_KEY = "profile_restore_offered";
  function _offeredAt(row) {
    var v = row && row.value;
    if (!v) return null;                       // never offered
    if (v === true) return 0;                  // legacy boolean — unknown, treat as ancient
    var t = Date.parse(v.at || v);
    return isFinite(t) ? t : 0;
  }
  eli.storage.get("config", OFFERED_KEY).then(function (row) {
    var lastOffer = _offeredAt(row);
    return _localTrophyCount().then(function (localCount) {
      if (localCount > 0) return;
      return _candidates({}).then(function (profiles) {
        if (!profiles.length) return;
        // An identical email address is proof of ownership, so zero trophies
        // plus a backup under that address is always worth raising — no
        // marker, no once-only. Restoring (or earning a trophy) ends it,
        // which is the only exit that should end it.
        var hasExact = profiles.some(function (p) { return p && p.exact; });
        if (!hasExact && lastOffer !== null) {
          // Initials-only matches might be somebody else, so those stay
          // gated: ask again only once a backup has been written since,
          // which means progress was made and then lost again.
          var fresher = profiles.some(function (p) {
            var t = Date.parse(p && p.lastSeenAt);
            return isFinite(t) && t > lastOffer;
          });
          if (!fresher) return;
        }
        return eli.storage.put("config", {
          key: OFFERED_KEY, value: { at: new Date().toISOString() },
        }).catch(function () { /* shown once is better than never shown */ })
          .then(function () { _offer(profiles); });
      });
    });
  }).catch(function (err) {
    eli.log.event("tool", "profile_restore_check_failed", { msg: err && err.message });
  });
}
